import { writeFileSync } from 'node:fs';
import { build } from 'vite';

const result = await build({
  configFile: false,
  publicDir: false,
  build: {
    write: false,
    minify: true,
    lib: { entry: 'src/lib/offline-game-shell.js', formats: ['iife'], name: 'OfflineGame' },
  },
});
const output = (Array.isArray(result) ? result[0] : result).output.find((item) => item.type === 'chunk');
if (!output) throw new Error('Offline game bootstrap was not built');
writeFileSync(
  'src/lib/offline-game-shell.generated.ts',
  '// Generated by scripts/build-offline-game.mjs\nexport const OFFLINE_GAME_SHELL = ' +
    JSON.stringify(output.code) +
    ';\n',
);
